// Call the target function to retrieve a const, library-owned, null-terminated string
const char *name = ecapture_project_name();
// Enforce that the returned pointer is non-null; bailing avoids propagating invalid state
if (!name) { FUZZ_BAIL(); }

// Validate that the string is null-terminated within a reasonable bound to prevent overreads
size_t max_scan = 1024; // keep bounded for fuzzer performance
size_t len = 0;
while (len < max_scan && name[len] != '\0') { ++len; }
if (len == max_scan) { FUZZ_BAIL(); }

// Prepare an output object matching the available ptr_type (const char **)
// Allocate a stable holder so the fuzzer runtime can manage it post-return
const char **project_name_ptr = new const char*; // never null after allocation
*project_name_ptr = name; // do NOT copy or free; ownership remains with the library

// Track attributes: ownership and observed length, to help downstream stubs enforce constraints
FUZZ_SET_ATTR_STR(project_name_ptr, "ownership", "library");
FUZZ_SET_ATTR_INT(project_name_ptr, "length", (int)len);

// Validation summary: Non-null and bounded null-termination enforced; output is a stable const char ** referencing the library-owned string.

